<?php
declare(strict_types=1);
[$config,$pdo]=require __DIR__.'/h2-bootstrap.php';$db=new MediaCentre\Storage\Database($pdo);
$admin=$db->one('SELECT * FROM admin_users WHERE login=?',['h3-test-admin']);$location=$db->one('SELECT id FROM locations ORDER BY created_at LIMIT 1');
if(!$admin||!$location)throw new RuntimeException('Run H3 isolated suites first.');
$pair=new MediaCentre\Security\PairingRepository($db);$issued=$pair->issue($admin['id'],(int)$admin['auth_revision'],$location['id'],null,MediaCentre\Security\ClientAccess::SCOPES);
$api=new MediaCentre\Http\Api($config,dirname(__DIR__));$ip='h5-'.bin2hex(random_bytes(8));
$paired=$api->handle('POST','/api/v1/pair',[],[],MediaCentre\Storage\Database::json(['code'=>$issued['code'],'client_name'=>'H5 radio test','client_version'=>'h5']),$ip);
if($paired['status']!==200)throw new RuntimeException('Isolated pairing failed.');$client=$paired['body']['data'];
$headers=['authorization'=>'Bearer '.$client['token'],'x-mediacentre-server-id'=>$client['server_id']];
$call=fn($method,$path,$body='',array $extra=[])=>$api->handle($method,'/api/v1/'.$path,[],$extra+$headers,$body,$ip);
$assert=fn($ok,$message)=>$ok ?: throw new RuntimeException($message);
$prefs=$call('GET','client/preferences');$payload=MediaCentre\Storage\Database::json(['revision'=>$prefs['body']['data']['revision'],'radio_volume'=>63]);
$assert($call('POST','client/preferences',$payload)['status']===428,'Compatibility POST skipped If-Match.');
$saved=$call('POST','client/preferences',$payload,['if-match'=>$prefs['headers']['ETag']]);
$assert($saved['status']===200 && $saved['body']['data']['radio_volume']===63,'API19-compatible volume write failed.');
$assert($call('POST','client/preferences',$payload,['if-match'=>$prefs['headers']['ETag']])['status']===412,'Compatibility POST skipped revision conflict.');
$assert($api->handle('POST','/api/v1/client/preferences',[],['cookie'=>'MCADMIN=anything'],$payload,$ip)['status']===401,'Admin cookie authorized API19 write.');
$station=MediaCentre\Shared\Uuid::random();(new MediaCentre\Radio\StationRepository($db))->create($station,'H5 radio','https://example.invalid/original',['Jazz'],'RU');
$assert($call('PUT','radio/favorites/'.$station)['status']===200,'Favorite write failed.');
$assert($call('GET','radio/stations/'.$station)['body']['data']['favorite']===true,'Player star not updated.');
$assert($call('GET','dashboard')['body']['data']['radio']['favorites'][0]['id']===$station,'Dashboard favorites not updated.');
$assert($call('DELETE','radio/favorites/'.$station)['status']===200 && $call('GET','radio/stations/'.$station)['body']['data']['favorite']===false,'Favorite removal not shared.');
$prefs=$call('GET','client/preferences');$payload=MediaCentre\Storage\Database::json(['revision'=>$prefs['body']['data']['revision'],'selected_station_id'=>$station]);
$assert($call('POST','client/preferences',$payload,['if-match'=>$prefs['headers']['ETag']])['status']===200 && $call('GET','bootstrap')['body']['data']['settings']['selected_station_id']===$station,'Selected original station not persisted.');
(new MediaCentre\Client\RightsRepository($db))->change($client['client_id'],1,['preferences:read','radio:read']);
$assert($call('POST','client/preferences',$payload,['if-match'=>$prefs['headers']['ETag']])['status']===403,'Compatibility write bypassed scopes.');
$pair->revoke($client['client_id'],2,$admin['id']);$assert($call('POST','client/preferences',$payload,['if-match'=>$prefs['headers']['ETag']])['status']===401,'Compatibility write bypassed revoke.');
echo "PASS: API19 POST keeps bearer/scopes/revoke/If-Match boundaries; volume, selected original station and shared favorite state persist.\n";
